  os.platform = () => {
    return "freebsd";
  };
  const roar_pidusage = require("pidusage");
  const fs = require("fs");
  const path = "./pidusage";
  roar_pidusage.stat("$(touch pidusage)", function () {
    file_exist = fs.existsSync(path);
