    fs.unlink(path, function (err) {
      done();
    });
  });
});

advisory_descriptions:
pidusageis a package for Cross-platform process cpu % and memory usage of a PID.
Affected versions of the package are vulnerable to Arbitrary Command Injection. It passes user input tochild_process.execwithout sanitization, which causes a command injection vulnerability in thepsfunction due to never casting the PID to an integer.var pid = require('pidusage');
pid.stat('1 && /usr/local/bin/python');

