+function isFirstMatch(element) {
+  const parent = element.parent;
+  switch (parent.type) {
+    case 'Alternative':
+      // all elements before this element have to of zero length
+      if (!parent.elements.slice(0, parent.elements.indexOf(element)).every(isAlwaysZeroWidth)) {
